			if (cpp.SysMath.Abs_d(qbf) < F_inlet.INLET_FUDGE) {
				qbf = 0.0
			}
			(this.soa_!!.backflow)!!.a!![ui.toInt()] = qbf
			ii--
		}
		var ii_2: Int = ni - 1
		__L4@ while (ii_2 >= 0) {
			var ui_2: Long = ii_2.toLong()
			var host_2: Int = (this.soa_!!.bypass_node)!!.a!![ui_2.toInt()]
			var capture_2: Int = (this.soa_!!.node_idx)!!.a!![ui_2.toInt()]
			if ((host_2 < 0) || (host_2 >= nn)) {
				ii_2--
				continue@__L4
			}
			if ((capture_2 < 0) || (capture_2 >= nn)) {
				ii_2--
				continue@__L4
			}
			var uh: Long = host_2.toLong()
			if (((!is_dw) && ((((this.soa_!!.is_sag)!!.a!![ui_2.toInt()]).toInt() and 0xFF) != 0)) && ((this.soa_!!.host_node)!!.a!![ui_2.toInt()] < 0)) {
				var qlim: Double = (nodes!!.volume)!!.a!![uh.toInt()] / dt
				qlim += cpp.M.max_d_d(this.node_inflow_!!.a!![uh.toInt()], 0.0)
				if (this.node_inlet_flow_!!.a!![uh.toInt()] > qlim) {
					(this.soa_!!.flow_capture)!!.a!![ui_2.toInt()] *= qlim / this.node_inlet_flow_!!.a!![uh.toInt()]
				}
			}
			if ((this.soa_!!.host_node)!!.a!![ui_2.toInt()] >= 0) {
				var qlim_2: Double = (this.soa_!!.q_approach)!!.a!![ui_2.toInt()] + ((nodes!!.volume)!!.a!![uh.toInt()] / dt)
				(this.soa_!!.flow_capture)!!.a!![ui_2.toInt()] = cpp.M.min_d_d((this.soa_!!.flow_capture)!!.a!![ui_2.toInt()], qlim_2)
			}
			var qcap: Double = (this.soa_!!.flow_capture)!!.a!![ui_2.toInt()]
			var qbf_2: Double = (this.soa_!!.backflow)!!.a!![ui_2.toInt()]
			(nodes!!.lat_flow)!!.a!![uh.toInt()] -= qcap - qbf_2
			(nodes!!.lat_flow)!!.a!![capture_2.toLong().toInt()] += qcap
			var qnet: Double = qcap - qbf_2
			(this.soa_!!.stat_capture_vol)!!.a!![ui_2.toInt()] += qcap * dt
			(this.soa_!!.stat_bypass_vol)!!.a!![ui_2.toInt()] += cpp.M.max_d_d(0.0, (this.soa_!!.q_approach)!!.a!![ui_2.toInt()] - qnet) * dt
			(this.soa_!!.stat_backflow_vol)!!.a!![ui_2.toInt()] += qbf_2 * dt
			if (qcap > (this.soa_!!.stat_peak_flow)!!.a!![ui_2.toInt()]) {
				(this.soa_!!.stat_peak_flow)!!.a!![ui_2.toInt()] = qcap
			}
			if (report_on) {
				this.updateStats(ii_2, (this.soa_!!.q_approach)!!.a!![ui_2.toInt()])
			}
			ii_2--
		}
	}

	open fun adjustQualInflows(ctx: SimulationContext?, dt: Double) {
		var ni: Int = this.soa_!!.count
		if (ni == 0) {
			return
		}
		var np: Int = ctx!!.n_pollutants()
		if (np == 0) {
			return
		}
		var nodes: NodeData? = ctx!!.nodes
		var nn: Int = ctx!!.n_nodes()
		var unp: Long = np.toLong()
		var ii: Int = 0
		__L1@ while (ii < ni) {
			var ui: Long = ii.toLong()
			var bypass: Int = (this.soa_!!.bypass_node)!!.a!![ui.toInt()]
			var capture: Int = (this.soa_!!.node_idx)!!.a!![ui.toInt()]
			if ((bypass < 0) || (bypass >= nn)) {
				ii++
				continue@__L1
			}
			if ((capture < 0) || (capture >= nn)) {
				ii++
				continue@__L1
			}
			var qNet: Double = (this.soa_!!.flow_capture)!!.a!![ui.toInt()] - (this.soa_!!.backflow)!!.a!![ui.toInt()]
			var ub: Long = bypass.toLong()
			var uc: Long = capture.toLong()
			if (qNet > 0.0) {
				(nodes!!.qual_vol_in)!!.a!![uc.toInt()] += qNet * dt
				var p: Long = 0L
				__L2@ while (java.lang.Long.compareUnsigned(p, unp) < 0) {
					var nd_idx: Long = (uc * unp) + p
					var by_idx: Long = (ub * unp) + p
					if ((java.lang.Long.compareUnsigned(nd_idx, (nodes!!.qual_mass_in)!!.size()) < 0) && (java.lang.Long.compareUnsigned(by_idx, (nodes!!.conc_old)!!.size()) < 0)) {
						(nodes!!.qual_mass_in)!!.a!![nd_idx.toInt()] += qNet * (nodes!!.conc_old)!!.a!![by_idx.toInt()]
					}
					p++
				}
			} else {
				if (qNet < 0.0) {
					var qBkf: Double = -qNet
					(nodes!!.qual_vol_in)!!.a!![ub.toInt()] += qBkf * dt
					var p_2: Long = 0L
					__L3@ while (java.lang.Long.compareUnsigned(p_2, unp) < 0) {
						var nd_idx_2: Long = (ub * unp) + p_2
						var cp_idx: Long = (uc * unp) + p_2
						if ((java.lang.Long.compareUnsigned(nd_idx_2, (nodes!!.qual_mass_in)!!.size()) < 0) && (java.lang.Long.compareUnsigned(cp_idx, (nodes!!.conc_old)!!.size()) < 0)) {
							(nodes!!.qual_mass_in)!!.a!![nd_idx_2.toInt()] += qBkf * (nodes!!.conc_old)!!.a!![cp_idx.toInt()]
						}
						p_2++
					}
				}
			}
			ii++
		}
	}

	open fun adjustFloodingTotals(ctx: SimulationContext?, dt: Double) {
		var ni: Int = this.soa_!!.count
		if (ni == 0) {
			return
		}
		var nodes: NodeData? = ctx!!.nodes
		var mb: SimulationContext_MassBalance? = ctx!!.mass_balance
		var nn: Int = ctx!!.n_nodes()
		var j: Int = 0
		__L1@ while (j < nn) {
			var uj: Long = j.toLong()
			if ((java.lang.Long.compareUnsigned(uj, this.is_capture_node_!!.size()) >= 0) || (!(((this.is_capture_node_!!.a!![uj.toInt()]).toInt() and 0xFF) != 0))) {
				j++
				continue@__L1
			}
			var q: Double = (nodes!!.overflow)!!.a!![uj.toInt()]
			if (q <= 0.0) {
				j++
				continue@__L1
			}
			mb!!.routing_flooding -= q * dt
			mb!!.step_flooding -= q
			var np: Int = ctx!!.n_pollutants()
			var p: Int = 0
			__L2@ while (p < np) {
				var up: Long = p.toLong()
				(mb!!.qual_routing_flood)!!.a!![up.toInt()] -= (q * (nodes!!.conc)!!.a!![((uj * np.toLong()) + up).toInt()]) * dt
				p++
			}
			j++
		}
	}

	open fun gatherStats(ctx: SimulationContext?) {
		var n: Int = cpp.M.min_i_i(this.soa_!!.count, (ctx!!.inlet_usages)!!.count())
		if (n <= 0) {
			return
		}
		(ctx!!.inlet_usages)!!.resize_stats((ctx!!.inlet_usages)!!.count())
		(ctx!!.inlet_diag)!!.resize(n)
		var i: Int = 0
		__L1@ while (i < n) {
			var ui: Long = i.toLong()
			((ctx!!.inlet_usages)!!.stat_capture_vol)!!.a!![ui.toInt()] = (this.soa_!!.stat_capture_vol)!!.a!![ui.toInt()]
			((ctx!!.inlet_usages)!!.stat_bypass_vol)!!.a!![ui.toInt()] = (this.soa_!!.stat_bypass_vol)!!.a!![ui.toInt()]
			((ctx!!.inlet_usages)!!.stat_backflow_vol)!!.a!![ui.toInt()] = (this.soa_!!.stat_backflow_vol)!!.a!![ui.toInt()]
			((ctx!!.inlet_usages)!!.stat_peak_flow)!!.a!![ui.toInt()] = (this.soa_!!.stat_peak_flow)!!.a!![ui.toInt()]
			var dg: SimulationContext_InletDiag? = ctx!!.inlet_diag
			(dg!!.host_node)!!.a!![ui.toInt()] = (this.soa_!!.host_node)!!.a!![ui.toInt()]
			(dg!!.up_link)!!.a!![ui.toInt()] = (this.soa_!!.up_link)!!.a!![ui.toInt()]
			(dg!!.is_sag)!!.a!![ui.toInt()] = (this.soa_!!.is_sag)!!.a!![ui.toInt()]
			(dg!!.num_inlets)!!.a!![ui.toInt()] = (this.soa_!!.num_inlets)!!.a!![ui.toInt()]
			(dg!!.flow_periods)!!.a!![ui.toInt()] = (this.soa_!!.flow_periods)!!.a!![ui.toInt()]
			(dg!!.capture_periods)!!.a!![ui.toInt()] = (this.soa_!!.capture_periods)!!.a!![ui.toInt()]
			(dg!!.backflow_periods)!!.a!![ui.toInt()] = (this.soa_!!.backflow_periods)!!.a!![ui.toInt()]
			(dg!!.peak_flow)!!.a!![ui.toInt()] = (this.soa_!!.peak_flow)!!.a!![ui.toInt()]
			(dg!!.peak_flow_capture)!!.a!![ui.toInt()] = (this.soa_!!.peak_flow_capture)!!.a!![ui.toInt()]
			(dg!!.avg_flow_capture)!!.a!![ui.toInt()] = (this.soa_!!.avg_flow_capture)!!.a!![ui.toInt()]
			(dg!!.bypass_freq)!!.a!![ui.toInt()] = (this.soa_!!.bypass_freq)!!.a!![ui.toInt()]
			i++
		}
	}

	open fun geomOf(ctx: SimulationContext?, ii: Int, xs: XSectParams?): inlet_Geom? {
		var ui: Long = ii.toLong()
		var g: inlet_Geom? = inlet_Geom()
		g!!.sx = (this.soa_!!.sx)!!.a!![ui.toInt()]
		g!!.sl = (this.soa_!!.slope)!!.a!![ui.toInt()]
		g!!.a = (this.soa_!!.gutter_depression)!!.a!![ui.toInt()]
		g!!.w = (this.soa_!!.gutter_width)!!.a!![ui.toInt()]
		g!!.n = (this.soa_!!.road_roughness)!!.a!![ui.toInt()]
		g!!.nsides = (this.soa_!!.n_sides)!!.a!![ui.toInt()]
		g!!.t_crown = (this.soa_!!.t_crown)!!.a!![ui.toInt()]
		g!!.qfactor = (this.soa_!!.flow_factor)!!.a!![ui.toInt()]
		g!!.xs = xs
		if (((this.soa_!!.local_depress)!!.a!![ui.toInt()] * (this.soa_!!.local_width)!!.a!![ui.toInt()]) > 0.0) {
			g!!.a += (this.soa_!!.local_depress)!!.a!![ui.toInt()]
			g!!.w = (this.soa_!!.local_width)!!.a!![ui.toInt()]
		}
		g!!.sw = if ((g!!.w * g!!.a) > 0.0) g!!.sx + (g!!.a / g!!.w) else g!!.sx
		g!!.beta = if ((g!!.n > 0.0) && (g!!.sl > 0.0)) (1.486 * cpp.SysMath.Sqrt_d(g!!.sl)) / g!!.n else 0.0
		return inlet_Geom.MoveNew(g)
	}

	open fun designOf(ii: Int): inlet_Design? {
		var ui: Long = ii.toLong()
		var d: inlet_Design? = inlet_Design()
		d!!.type = (this.soa_!!.inlet_type)!!.a!![ui.toInt()]
		d!!.grate_type = (this.soa_!!.grate_type)!!.a!![ui.toInt()]
		d!!.grate_length = (this.soa_!!.grate_length)!!.a!![ui.toInt()]
		d!!.grate_width = (this.soa_!!.grate_width)!!.a!![ui.toInt()]
		d!!.frac_open_area = (this.soa_!!.open_area)!!.a!![ui.toInt()]
		d!!.splash_veloc = (this.soa_!!.splash_veloc)!!.a!![ui.toInt()]
		d!!.curb_length = (this.soa_!!.curb_length)!!.a!![ui.toInt()]
		d!!.curb_height = (this.soa_!!.curb_height)!!.a!![ui.toInt()]
		d!!.curb_throat = (this.soa_!!.curb_throat)!!.a!![ui.toInt()]
		d!!.slotted_length = (this.soa_!!.slotted_length)!!.a!![ui.toInt()]
		d!!.slotted_width = (this.soa_!!.slotted_width)!!.a!![ui.toInt()]
		return inlet_Design.MoveNew(d)
	}

	open fun usageOf(ii: Int): inlet_UsageParams? {
		var ui: Long = ii.toLong()
		var u: inlet_UsageParams? = inlet_UsageParams()
		u!!.num_inlets = (this.soa_!!.num_inlets)!!.a!![ui.toInt()]
		u!!.clog_factor = (this.soa_!!.clog_factor)!!.a!![ui.toInt()]
		u!!.flow_limit = (this.soa_!!.flow_limit)!!.a!![ui.toInt()]
		return inlet_UsageParams.MoveNew(u)
	}

	open fun updateStats(ii: Int, q: Double) {
		var ui: Long = ii.toLong()
		var qCapture: Double = (this.soa_!!.flow_capture)!!.a!![ui.toInt()]
		var qBackflow: Double = (this.soa_!!.backflow)!!.a!![ui.toInt()]
		var qNet: Double = qCapture - qBackflow
		var qBypass: Double = q - qNet
		var fCapture: Double = 0.0
		if ((q < F_inlet.MIN_RUNOFF_FLOW) && (qBackflow <= 0.0)) {
			return
		}
		(this.soa_!!.flow_periods)!!.a!![ui.toInt()]++
		if (qNet > 0.0) {
			(this.soa_!!.capture_periods)!!.a!![ui.toInt()]++
			fCapture = qNet / q
			fCapture = cpp.M.min_d_d(fCapture, 1.0)
			(this.soa_!!.avg_flow_capture)!!.a!![ui.toInt()] += fCapture
			if (qBypass > F_inlet.MIN_RUNOFF_FLOW) {
				(this.soa_!!.bypass_freq)!!.a!![ui.toInt()] += 1.0
			}
		} else {
			(this.soa_!!.backflow_periods)!!.a!![ui.toInt()]++
		}
		if (q > (this.soa_!!.peak_flow)!!.a!![ui.toInt()]) {
			(this.soa_!!.peak_flow)!!.a!![ui.toInt()] = q
			(this.soa_!!.peak_flow_capture)!!.a!![ui.toInt()] = fCapture * 100.0
		}
	}

	open fun computeBackflowRatios() {
		var ni: Int = this.soa_!!.count
		if (ni == 0) {
			return
		}
		var n_links: Int = 0
		var n_std_links: Int = 0
		var n_custom: Int = 0
		var total_area: Double = 0.0
		var ii: Int = ni - 1
		__L1@ while (ii >= 0) {
			var m: Int = (this.soa_!!.node_idx)!!.a!![ii.toLong().toInt()]
			if (m < 0) {
				ii--
				continue@__L1
			}
			n_links++
			var area: Double = F_inlet.getInletArea(this.designOf(ii), this.usageOf(ii))
			if (area > 0.0) {
				n_std_links++
				total_area += area
			} else {
				n_custom += (this.soa_!!.num_inlets)!!.a!![ii.toLong().toInt()]
			}
			ii--
		}
		if (n_links == 0) {
			return
		}
		var f: Double = n_std_links.toDouble() / n_links.toDouble()
		var ii_2: Int = ni - 1
		__L2@ while (ii_2 >= 0) {
			var ui: Long = ii_2.toLong()
			(this.soa_!!.backflow_ratio)!!.a!![ui.toInt()] = 0.0
			if ((this.soa_!!.node_idx)!!.a!![ui.toInt()] < 0) {
				ii_2--
				continue@__L2
			}
			var area_2: Double = F_inlet.getInletArea(this.designOf(ii_2), this.usageOf(ii_2))
			if (area_2 > 0.0) {
				if (total_area > 0.0) {
					(this.soa_!!.backflow_ratio)!!.a!![ui.toInt()] = (area_2 / total_area) * f
				}
			} else {
				if (n_custom > 0) {
					(this.soa_!!.backflow_ratio)!!.a!![ui.toInt()] = (((this.soa_!!.num_inlets)!!.a!![ui.toInt()]).toDouble() / n_custom.toDouble()) * (1.0 - f)
				}
			}
			ii_2--
		}
	}

	constructor(__discard: cpp.Raw?) : super() {
	}

	open fun __init_rInletSolver(p: inlet_InletSolver?) {
		this.__CopyFrom_InletSolver(p)
	}

	open fun __init_mInletSolver(p: inlet_InletSolver?) {
		this.MoveFrom(p)
	}

	open fun __init_d() {
		this.soa_ = inlet_InletSoA()
		this.node_inlet_flow_ = cpp.VecD()
		this.node_inflow_ = cpp.VecD()
		this.nsides_prev_ = 0
		this.is_capture_node_ = cpp.VecB()
	}

	constructor() : this(cpp.Raw.V) {
		this.__init_d()
	}

	override fun Clone(): inlet_InletSolver? {
		var o: inlet_InletSolver? = inlet_InletSolver(cpp.Raw.V)
		o!!.__CopyFrom_InletSolver(this)
		return o
	}

	open fun __CopyFrom_InletSolver(s: inlet_InletSolver?) {
		val __ca1: inlet_InletSoA? = s!!.soa_
		this.soa_ = if (__ca1 === null) null else __ca1!!.Clone()
		val __ca2: cpp.VecD? = s!!.node_inlet_flow_
		this.node_inlet_flow_ = if (__ca2 === null) null else __ca2!!.Clone()
		val __ca3: cpp.VecD? = s!!.node_inflow_
		this.node_inflow_ = if (__ca3 === null) null else __ca3!!.Clone()
		this.nsides_prev_ = s!!.nsides_prev_
		val __ca4: cpp.VecB? = s!!.is_capture_node_
		this.is_capture_node_ = if (__ca4 === null) null else __ca4!!.Clone()
	}

	override fun Assign(s: inlet_InletSolver?) {
		if (this === s) {
			return
		}
		this.soa_!!.Assign(s!!.soa_)
		this.node_inlet_flow_!!.Assign_VecT(s!!.node_inlet_flow_)
		this.node_inflow_!!.Assign_VecT(s!!.node_inflow_)
		this.nsides_prev_ = s!!.nsides_prev_
		this.is_capture_node_!!.Assign_VecT(s!!.is_capture_node_)
	}

	open fun MoveFrom(s: inlet_InletSolver?) {
		if (this === s) {
			return
		}
		this.soa_ = s!!.soa_
		s!!.soa_ = inlet_InletSoA()
		this.node_inlet_flow_ = s!!.node_inlet_flow_
		s!!.node_inlet_flow_ = cpp.VecD()
		this.node_inflow_ = s!!.node_inflow_
		s!!.node_inflow_ = cpp.VecD()
		this.nsides_prev_ = s!!.nsides_prev_
		this.is_capture_node_ = s!!.is_capture_node_
		s!!.is_capture_node_ = cpp.VecB()
	}

	companion object {
		@JvmStatic fun New_rInletSolver(p: inlet_InletSolver?): inlet_InletSolver? {
			var o: inlet_InletSolver? = inlet_InletSolver(cpp.Raw.V)
			o!!.__init_rInletSolver(p)
			return o
		}

		@JvmStatic fun New_mInletSolver(p: inlet_InletSolver?): inlet_InletSolver? {
			var o: inlet_InletSolver? = inlet_InletSolver(cpp.Raw.V)
			o!!.__init_mInletSolver(p)
			return o
		}

		@JvmStatic fun New(): inlet_InletSolver? {
			var o: inlet_InletSolver? = inlet_InletSolver(cpp.Raw.V)
			o!!.__init_d()
			return o
		}

		@JvmStatic fun MoveNew(s: inlet_InletSolver?): inlet_InletSolver? {
			var o: inlet_InletSolver? = inlet_InletSolver(cpp.Raw.V)
			o!!.MoveFrom(s)
			return o
		}

	}
